package com.cpf.education.online.querypaging.service;
import com.cpf.core.api.error.CpfNotFoundException;import com.cpf.data.persistence.api.*;import com.cpf.data.persistence.api.page.*;import com.cpf.education.online.querypaging.dto.*;import com.cpf.education.online.querypaging.model.MemberView;import com.cpf.foundation.annotation.CpfService;import java.util.List;import org.springframework.beans.factory.ObjectProvider;
/** 조회·검색·Paging 교육 예제의 Service 역할과 CPF 표준 사용 경계를 보여줍니다. */
@CpfService public class MemberSearchService {private final ObjectProvider<CpfPagingAndSortingRepository<MemberView,MemberSearch>> repositories;public MemberSearchService(ObjectProvider<CpfPagingAndSortingRepository<MemberView,MemberSearch>> r){repositories=r;}public SearchResult search(SearchMode mode,String memberId,String name,int page,int size){var repo=repository();var criteria=new MemberSearch(memberId,name);var request=new CpfPageRequest(page,size);var sorts=List.of(CpfSort.asc("memberId"));return switch(mode){case PAGE->new SearchResult(mode,repo.findAll(criteria,request,sorts));case SLICE->new SearchResult(mode,repo.findSlice(criteria,request,sorts));case DETAIL->{if(memberId==null||memberId.isBlank())throw new IllegalArgumentException("DETAIL mode requires memberId");var result=repo.findAll(criteria,new CpfPageRequest(0,1),sorts);var detail=result.content().stream().findFirst().orElseThrow(()->new CpfNotFoundException("회원이 없습니다: "+memberId));yield new SearchResult(mode,detail);}};}private CpfPagingAndSortingRepository<MemberView,MemberSearch> repository(){var r=repositories.getIfAvailable();if(r==null)throw new IllegalStateException("CPF paging repository provider is not configured");return r;}}
